mapper.insert:
INSERT INTO training_sessions (
    user_id
  , training_type
  , pose_scenario_id
  , started_at
  , ended_at
  , score
) VALUES (
    #{session.userId}
  , #{session.trainingType}
  , #{session.poseScenarioId}
  , NOW() - INTERVAL #{elapsedSec} SECOND
  , NOW()
  , #{session.score}
)

INSERT INTO session_results (
    session_id
  , result_type
  , pose_step_id
  , item_order
  , score
  , attempts
  , detail_json
) VALUES (
    #{sessionId}
  , #{resultType}
  , #{poseStepId}
  , #{itemOrder}
  , #{score}
  , #{attempts}
  , #{detailJson}
)
